const reverseDictionary = Object.fromEntries(
  Object.entries(dictionary).map(([a, b]) => [b, a]),
);
let preferences = { language: "zh", theme: "light" };
try {
  const saved = JSON.parse(localStorage.getItem("doujian-preferences"));
  if (saved) {
    preferences.language = saved.language === "en" ? "en" : "zh";
    preferences.theme = saved.theme === "dark" ? "dark" : "light";
  }
} catch {}
function tr(text) {
  const raw = String(text ?? ""),
    s = raw.trim(),
    zh = reverseDictionary[s] || s;
  return raw.replace(
    s,
    preferences.language === "en" ? dictionary[zh] || zh : zh,
  );
}
function localize() {
  document.documentElement.lang =
    preferences.language === "en" ? "en" : "zh-CN";
  document.documentElement.dataset.theme = preferences.theme;
  document.title =
    preferences.language === "en"
      ? "Bean Journal · Coffee notebook"
      : "豆间 · 咖啡手记";
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const n of nodes) {
    if (n.parentElement.closest("script,style,textarea,[data-user],.brand"))
      continue;
    const next = tr(n.nodeValue);
    if (next !== n.nodeValue) n.nodeValue = next;
  }
  document.querySelectorAll("[placeholder],[aria-label]").forEach((el) => {
    for (const attr of ["placeholder", "aria-label"])
      if (el.hasAttribute(attr))
        el.setAttribute(attr, tr(el.getAttribute(attr)));
  });
  $("#languageSelect").value = preferences.language;
  $("#themeSelect").value = preferences.theme;
  localizeDateInputs();
}
document.documentElement.dataset.theme = preferences.theme;
function savePreference(key, value) {
  const next = { ...preferences, [key]: value };
  try {
    localStorage.setItem("doujian-preferences", JSON.stringify(next));
    preferences = next;
    render();
    localize();
  } catch {
    toast("设置保存失败，请检查浏览器存储");
  }
}
document.querySelector("#settingsButton").onclick = () => {
  localize();
  document.querySelector("#settingsDialog").showModal();
};
document.querySelector("#closeSettings").onclick = () =>
  document.querySelector("#settingsDialog").close();
document.querySelector("#languageSelect").onchange = (e) =>
  savePreference("language", e.target.value);
document.querySelector("#themeSelect").onchange = (e) =>
  savePreference("theme", e.target.value);
let draftPhoto = "",
  photoBusy = false,
  photoGeneration = 0;

function attachPhotoEditor(item) {
  draftPhoto = safePhoto(item.photo) ? item.photo : "";
  const box = document.createElement("section");
  box.className = "photo-editor wide";
  box.innerHTML =
    '<h3>豆卡照片</h3><p class="meta">照片仅在详情中显示，不会用作豆卡封面。</p><div id="photoPreview"></div><div class="photo-actions"><label class="outline photo-upload"><span id="photoLabel">上传照片</span><input type="file" id="beanPhoto" accept="image/jpeg,image/png,image/webp"></label><button type="button" id="removePhoto" class="danger">移除照片</button></div><p class="meta">支持 JPG、PNG、WebP，最大 10 MB。保存前自动压缩。</p>';
  $("#fields").append(box);
  updatePhotoPreview();
  $("#removePhoto").onclick = () => {
    photoGeneration++;
    draftPhoto = "";
    photoBusy = false;
    $("#beanPhoto").value = "";
    updatePhotoPreview();
  };
  $("#beanPhoto").onchange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (
      file.size > 10 * 1024 * 1024 ||
      !["image/jpeg", "image/png", "image/webp"].includes(file.type)
    ) {
      toast("请选择 10 MB 以内的 JPG、PNG 或 WebP 照片");
      e.target.value = "";
      return;
    }
    const generation = ++photoGeneration;
    photoBusy = true;
    toast("照片处理中，请稍候");
    try {
      const photo = await resizePhoto(file);
      if (generation !== photoGeneration) return;
      draftPhoto = photo;
      updatePhotoPreview();
    } catch {
      if (generation === photoGeneration)
        toast("照片处理失败，请换一张照片重试");
    } finally {
      if (generation === photoGeneration) {
        photoBusy = false;
        e.target.value = "";
      }
    }
  };
}
function updatePhotoPreview() {
  const container = $("#photoPreview");
  container.replaceChildren();
  if (draftPhoto) {
    const image = document.createElement("img");
    image.src = draftPhoto;
    image.alt = tr("豆卡照片");
    container.append(image);
  } else {
    const empty = document.createElement("p");
    empty.className = "photo-empty";
    empty.textContent = tr("暂无照片");
    container.append(empty);
  }
  $("#photoLabel").textContent = draftPhoto ? "更换照片" : "上传照片";
  $("#removePhoto").hidden = !draftPhoto;
  localize();
}
async function resizePhoto(file) {
  const image = await createImageBitmap(file);
  try {
    if (!image.width || !image.height) throw Error("Empty image");
    const scale = Math.min(1, 1200 / Math.max(image.width, image.height)),
      canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.round(image.width * scale));
    canvas.height = Math.max(1, Math.round(image.height * scale));
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
    let result = canvas.toDataURL("image/jpeg", 0.8);
    if (result.length > 800000) result = canvas.toDataURL("image/jpeg", 0.6);
    if (!safePhoto(result)) throw Error("Photo too large");
    return result;
  } finally {
    image.close();
  }
}

function validateDateField(input) {
  const valid =
    (!input.value && !input.required) || validDateValue(input.value);
  input.setCustomValidity(valid ? "" : tr("请输入有效日期，格式为 YYYY-MM-DD"));
  return valid;
}
function localizeDateInputs() {
  document
    .querySelectorAll(
      "input[type=date]:not([data-date-picker]),input[data-date-input]",
    )
    .forEach((input) => {
      input.dataset.dateInput = "true";
      const value = input.value;
      input.type = "text";
      input.placeholder = "YYYY-MM-DD";
      input.maxLength = 10;
      input.setAttribute("pattern", "[0-9]{4}-[0-9]{2}-[0-9]{2}");
      input.setAttribute("aria-description", "YYYY-MM-DD");
      input.value = value;
      let wrapper = input.closest(".date-field");
      if (!wrapper) {
        wrapper = document.createElement("span");
        wrapper.className = "date-field";
        input.before(wrapper);
        wrapper.append(input);
        const control = document.createElement("span");
        control.className = "date-picker-control";
        control.innerHTML =
          '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 5h14v16H5zM5 10h14M8 2v6M16 2v6M8 14h2M14 14h2M8 17h2"/></svg>';
        const picker = document.createElement("input");
        picker.type = "date";
        picker.dataset.datePicker = "true";
        picker.onchange = () => {
          input.value = picker.value;
          input.dispatchEvent(new Event("input", { bubbles: true }));
          input.dispatchEvent(new Event("change", { bubbles: true }));
        };
        // Keep the native date control for mobile Safari and desktop calendars.
        picker.onclick = () => {
          if (typeof picker.showPicker === "function") {
            try {
              picker.showPicker();
            } catch {
              /* Native click remains available. */
            }
          }
        };
        control.append(picker);
        wrapper.append(control);
      }
      const picker = wrapper.querySelector("[data-date-picker]");
      picker.setAttribute(
        "aria-label",
        preferences.language === "en" ? "Choose date" : "选择日期",
      );
      picker.value = validDateValue(input.value) ? input.value : "";
      input.oninput = () => {
        validateDateField(input);
        picker.value = validDateValue(input.value) ? input.value : "";
      };
      input.oninvalid = () => validateDateField(input);
      if (input.value) validateDateField(input);
      else input.setCustomValidity("");
    });
}
function validateDateInputs() {
  let valid = true;
  document.querySelectorAll("#form input[data-date-input]").forEach((input) => {
    if (!validateDateField(input)) valid = false;
  });
  if (!valid) $("#form").reportValidity();
  return valid;
}
